import { z } from "zod";
export var UKCountry;
(function (UKCountry) {
    UKCountry["England"] = "England";
    UKCountry["Scotland"] = "Scotland";
    UKCountry["Wales"] = "Wales";
    UKCountry["NorthernIreland"] = "Northern Ireland";
})(UKCountry || (UKCountry = {}));
export var UKCountryAbbreviation;
(function (UKCountryAbbreviation) {
    UKCountryAbbreviation["England"] = "ENG";
    UKCountryAbbreviation["Scotland"] = "SCO";
    UKCountryAbbreviation["Wales"] = "WAL";
    UKCountryAbbreviation["NorthernIreland"] = "NIR";
})(UKCountryAbbreviation || (UKCountryAbbreviation = {}));
export const UKCountrySchema = z
    .union([
    z.nativeEnum(UKCountry), // Accept full country name
    z.nativeEnum(UKCountryAbbreviation), // Accept country abbreviation
])
    .transform((country) => {
    if (country in UKCountryAbbreviation) {
        return country;
    }
    return UKCountryAbbreviation[UKCountry[country]];
});
